import{_ as e}from"./chunks/chauffeur-workspace.Dz09cZIH.js";import{_ as l,o as r,c as t,a2 as o}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Χώρος εργασίας οδηγού","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/chauffeur-workspace.md","filePath":"el/plus/chauffeur-workspace.md"}'),i={name:"el/plus/chauffeur-workspace.md"};function s(h,a,p,n,c,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="χωρος-εργασιας-οδηγου" tabindex="-1">Χώρος εργασίας οδηγού <a class="header-anchor" href="#χωρος-εργασιας-οδηγου" aria-label="Permalink to &quot;Χώρος εργασίας οδηγού&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>TransferBook+ v0.7.9: προσχέδιο ελεγμένο στον πηγαίο κώδικα. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις· δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/chauffeur-workspace.png"><img src="'+e+'" alt="Χώρος εργασίας οδηγού από την προβολή διαχειριστή: ελέγξτε την ανάθεση, τις οδηγίες παραλαβής και τις σημειώσεις πριν αποδεχθείτε το δρομολόγιο."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Χώρος εργασίας οδηγού από την προβολή διαχειριστή: ελέγξτε την ανάθεση, τις οδηγίες παραλαβής και τις σημειώσεις πριν αποδεχθείτε το δρομολόγιο.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><p>Ελέγξτε τις ανατεθειμένες διαδρομές και καταγράψτε επιτρεπόμενη πρόοδο και επιχειρησιακές σημειώσεις.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένο περιβάλλον, επιβεβαιώστε εταιρεία και ρόλο και χρησιμοποιήστε συνθετικά στοιχεία για εκπαίδευση.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Συνδεθείτε με εξουσιοδοτημένο λογαριασμό οδηγού σε εγκεκριμένο περιβάλλον. Στην επίδειξη, η επιλογή οδηγού είναι προσομοίωση ταυτότητας, όχι πιστοποίηση.</li><li>Ελέγξτε την ανατεθειμένη κράτηση, την ώρα και την τοποθεσία παραλαβής. Χρησιμοποιήστε την επιτρεπόμενη ενέργεια προόδου μόνο όταν πραγματοποιηθεί το αντίστοιχο στάδιο.</li><li>Προσθέστε σύντομη επιχειρησιακή σημείωση όταν χρειάζεται. Χρησιμοποιήστε την πινακίδα υποδοχής μόνο για τον ανατεθειμένο επιβάτη και αποφύγετε περιττή έκθεση στοιχείων.</li></ol><h2 id="επαληθευση-και-αντιμετωπιση-προβληματων" tabindex="-1">Επαλήθευση και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#επαληθευση-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Επαλήθευση και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν λείπει διαδρομή ή ενέργεια, επικοινωνήστε με τον υπεύθυνο αναθέσεων. Μη χρησιμοποιείτε άλλη ταυτότητα οδηγού και μη θεωρείτε ότι η ενημέρωση στέλνει εξωτερικό μήνυμα.</p><h2 id="σχετικοι-οδηγοι" tabindex="-1">Σχετικοί οδηγοί <a class="header-anchor" href="#σχετικοι-οδηγοι" aria-label="Permalink to &quot;Σχετικοί οδηγοί&quot;">​</a></h2><ul><li><a href="/el/plus/">Εγχειρίδιο χειριστή</a></li><li><a href="/el/plus/reservations.html">Κρατήσεις</a></li><li><a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a></li></ul><h2 id="λειτουργια-σκελων-v0-7-26" tabindex="-1">Λειτουργία σκελών v0.7.26 <a class="header-anchor" href="#λειτουργια-σκελων-v0-7-26" aria-label="Permalink to &quot;Λειτουργία σκελών v0.7.26&quot;">​</a></h2><p>Συνδεθείτε με πραγματικό εξουσιοδοτημένο λογαριασμό οδηγού. Ελέγξτε κάθε ανάθεση μετάβασης ή επιστροφής, αποδεχτείτε ή απορρίψτε μέσω υποστηριζόμενης ροής και προχωρήστε μόνο το σωστό σκέλος. Η ολοκλήρωση μετάβασης δεν ολοκληρώνει επιστροφή. Επιβεβαιώστε οδηγίες παραλαβής και εγκεκριμένη ειδοποίηση άφιξης. Αν είναι εγκεκριμένη και διαθέσιμη κοινοποίηση GPS, ενεργοποιήστε ρητά εντός βάρδιας και διακόψτε όταν παύει η εξουσιοδότηση. Σε ληγμένη συνεδρία ή offline αποκαταστήστε την πρόσβαση πριν από υποβολή.</p><p>Για μερικά ή πλήρη μετρητά δείτε <a href="/el/plus/cash-management.html">Διαχείριση μετρητών</a>· η παράδοση στο γραφείο είναι χωριστή. Δείτε <a href="/el/plus/arrival-intelligence.html">Αφίξεις</a> και <a href="/el/plus/staff-administration.html">Προσωπικό</a>.</p>',19)])])}const _=l(i,[["render",s]]);export{m as __pageData,_ as default};
